"""Machine-readable source, discovery and unresolved-requirement delivery files."""
import json
from collections import defaultdict


def delivery_metadata(library):
 coverage=library.coverage();requests=defaultdict(list);documents=defaultdict(list)
 datasets={r['dataset_id']:r for r in coverage['datasets']};header_job=coverage['jobs'].get('ethereum-header-backfill',{})
 header_complete=bool(header_job.get('source_range_complete')) and datasets.get('network.ethereum.base_fee.daily',{}).get('status')=='complete'
 with library.connect(readonly=True) as c:
  sources=[{'source_id':r['source_id'],**json.loads(r['body'])} for r in c.execute('SELECT * FROM sources ORDER BY source_id')]
  for r in c.execute('SELECT * FROM captures ORDER BY retrieved_at'):requests[r['url']].append({'capture_id':r['capture_id'],'retrieved_at':r['retrieved_at'],'status':r['status'],'error':r['error'],'sha256':r['sha256']})
  for r in c.execute('SELECT d.url,v.record_id,v.capture_id,v.known_at FROM documents d JOIN document_versions v USING(document_id)'):documents[r['url']].append(dict(r))
  discoveries=[]
  for r in c.execute('SELECT * FROM discoveries ORDER BY source_id,url'):
   row=dict(r);row['metadata']=json.loads(row.pop('body'));row['capture_attempts']=requests.get(row['url'],[]);row['versions']=documents.get(row['url'],[]);discoveries.append(row)
  aliases=[{'record_id':r['record_id'],'variants':json.loads(r['body']).get('variants',[])} for r in c.execute("SELECT * FROM legacy WHERE json_extract(body,'$.dataset_id')='local.ambiguous_legacy_alias'")]
 gaps={'numeric_contracts':[{'dataset_id':r['dataset_id'],'records':r['records'],'missing_fields':r['null_counts'],'coverage_status':r['status'],'source_attempt':r['job']} for r in coverage['datasets'] if r['status']!='complete'],
       'follow_up_access_checks':{k:v for k,v in coverage['jobs'].items() if k.startswith('followup:')},
       'text_outcomes':[r for r in coverage['text_discoveries'] if r['status'] not in ('saved','excluded')],
       'discovery_incomplete':{k:v for k,v in coverage['jobs'].items() if k.startswith('text:') and not v.get('discovery_complete')},
       'legacy_alias_ambiguities':aliases,
       'legitimate_no_observation':[{'dataset_id':r['dataset_id'],'dates':r['nonobservation_dates'],'reason':r['job'].get('reason')} for r in coverage['datasets'] if r['nonobservation_dates'] or r['availability_state']=='legitimate_no_observation'],
       'awaiting_publication':[{'dataset_id':r['dataset_id'],'dates':r['pending_publication_dates']} for r in coverage['datasets'] if r['pending_publication_dates']],
       'public_alternatives':{**({'market.coinbase.hourly_reference':'market.bitstamp.{eth,btc}.hourly (independent venue; Coinbase gaps remain)','macro.fred.treasury_reference':'macro.treasury.cmt{2,10}.daily (independent official Treasury par-yield source; FRED/H15 gaps remain)','network.ethereum.base_fee.daily':'analysis.eth.base_fee_ratio_proxy.daily (optional burn/gas ratio; uncertain publisher scope, not arithmetic block mean)'} if library.days>31 else {}),'network.coinmetrics.eth.daily.gas_used':'network.etherscan.gas.daily','network.coinmetrics.eth.daily.mean_fee_eth':'analysis.eth.network.daily (explicit arithmetic quotient; not licensed FeeMeanNtv)','network.coinmetrics.eth.supply.signed_burn_eth':'network.etherscan.burn.daily (source-specific execution fee burn, not automatically an equivalent supply metric)'},
       'native_execution_header_alternative':{'state':'complete' if header_complete else 'not_yet_complete','resource_policy':'A half-year raw-header scan is not launched automatically; low-volume daily ratio proxy remains separate and uncertain' if library.days>31 else 'Monthly native header scope','collector_status':header_job.get('status'),'acquired_headers':header_job.get('block_headers',0),'expected_headers':header_job.get('end_block_exclusive',0)-header_job.get('first_block',0),'base_fee_dataset':'network.ethereum.base_fee.daily','execution_dataset':'network.ethereum.execution.daily','method':'Permitted public eth_getBlockByNumber; mean baseFeePerGas, gasUsed sum and sum(baseFeePerGas*gasUsed) from a complete, parent-linked configured-window range. Does not require historical eth_feeHistory.','scope':'Execution base-fee burn excludes blob burn, consensus issuance and slashing; it does not fill a source-specific signed supply-burn or staking metric.'},
       'native_fee_burn_alternative':{'dataset_id':'network.ethereum.fee_burn.daily','state':datasets.get('network.ethereum.fee_burn.daily',{}).get('status','not_yet_derived'),'method':'Execution + blob fee burn from complete admitted headers and a pinned actual mainnet blob schedule. No additional data credentials.','scope':'A separate fee-burn calculation, not a licensed Coin Metrics observation, net supply change, issuance or staking/consensus-penalty measure.'},
       'additional_access':[
        {'source':'Coin Metrics','requested':'FeeMeanNtv/SplyBurntNtv on eth; SplyStkedNtv/ValidatorActOngCnt on documented consensus-layer asset eth_cl, '+library.window_start[:10]+' through '+(library.end-__import__('datetime').timedelta(days=1)).date().isoformat()+' daily','observed':'Original eth staking requests returned400 because they used the execution asset; corrected eth_cl staking/validator requests return403. FeeMeanNtv/SplyBurntNtv also return403. GasUsed remains unavailable on that community source; Etherscan gas is a separate available alternative.','next_step':'Obtain an independent vendor entitlement for the exact asset/metrics/window; do not reuse a model-provider key','price':'Not verified; a vendor/account quote is required. No purchase or paid endpoint enabled.','documentation':'https://gitbook-docs.coinmetrics.io/network-data/network-data-overview/supply/validator-supply'},
        {'source':'PublicNode historical execution RPC','requested':'Historical eth_feeHistory for daily base fee aggregation across the configured window','observed':'Mainnet/finalized/historical headers available; two-block historical feeHistory request returns403 with an explicit personal-token requirement. Cloudflare returned Cannot fulfill request and Llama did not return a usable JSON-RPC response.','next_step':'No extra access is required for the admitted raw-header alternative; inspect native_execution_header_alternative. A separate token would only be needed to use the restricted feeHistory method.','price':'Not verified; the official token portal did not expose a readable quote. No new service enabled.','documentation':'https://ethereum.github.io/execution-apis/api/methods/eth_feeHistory/','account_portal':'https://www.allnodes.com/publicnode'},
        {'source':'beaconcha.in','requested':'Daily historical network staking scale and yield reference; exact history/aggregation entitlement must be confirmed','observed':'Public ETHstore route required independent authentication; dashboard/pricing capture HTTP403','next_step':'Use a separately authorized API account only after daily history, network scope and ETH.STORE license rights are confirmed','price':'Not verified; official pricing page inaccessible to the collector. No paid service enabled.','documentation':'https://docs.beaconcha.in/api-reference/ethereum/eth-store','pricing':'https://www.beaconcha.in/pricing?product=api'},
        {'source':'CoinDesk','requested':'Original bodies for within-window dated articles; see the exact current count in text_outcomes','observed':'Specific publisher AI-crawler restrictions; metadata retained without bulk body capture','next_step':'Obtain authorized/licensed original-text access; do not substitute snippets as full text','price':'No public license quote verified; publisher permission/quote required','documentation':'https://www.coindesk.com/robots.txt'}],
       'state':'Full required-core acceptance remains false while unresolved requirements exist; available validated records can be used with coverage checks.'}
 return {'SOURCES.json':{'sources':sources,'requests':[{'url':url,'attempts':attempts} for url,attempts in requests.items()]},'DISCOVERY.json':discoveries,'GAPS.json':gaps}
